package com.shopsphere.dao;
import com.shopsphere.util.DB;import java.sql.*;import java.util.*;
public class CartDAO {
 public List<Map<String,Object>> items(int uid)throws SQLException {List<Map<String,Object>> out=new ArrayList<>();try(Connection c=DB.connect();PreparedStatement s=c.prepareStatement("SELECT c.product_id,c.quantity,p.name,p.image_url,p.stock,ROUND(p.price*(100-p.discount)/100,2) sale_price FROM cart c JOIN products p ON p.product_id=c.product_id WHERE c.user_id=? AND p.status=TRUE")){s.setInt(1,uid);try(ResultSet r=s.executeQuery()){while(r.next()){Map<String,Object> m=new HashMap<>();for(String k:List.of("product_id","quantity","name","image_url","stock","sale_price"))m.put(k,r.getObject(k));out.add(m);}}}return out;}
 public void change(int uid,int pid,int qty)throws SQLException {try(Connection c=DB.connect()) {if(qty<=0){try(PreparedStatement s=c.prepareStatement("DELETE FROM cart WHERE user_id=? AND product_id=?")){s.setInt(1,uid);s.setInt(2,pid);s.executeUpdate();}}else {try(PreparedStatement s=c.prepareStatement("INSERT INTO cart(user_id,product_id,quantity) SELECT ?,product_id,? FROM products WHERE product_id=? AND status=TRUE AND stock>=? ON DUPLICATE KEY UPDATE quantity=VALUES(quantity)")){s.setInt(1,uid);s.setInt(2,qty);s.setInt(3,pid);s.setInt(4,qty);if(s.executeUpdate()==0)throw new SQLException("Invalid product or insufficient stock");}}}}
}
